// Reference-vector generator for the lobby wire format (max_net::wire::lobby).
//
// The C++ headless (max-cpp-port/src/remote.cpp) is the canon. This program
// contains a self-contained copy of the lobby serializers used by
// Remote_SendNetPacket_30/37/44/47 and Remote_WriteNetNode, with the **real**
// `NetAddress` aggregate taken from max-cpp-port/src/net_address.hpp, so the
// generated bytes include the same struct padding the game sends.
//
// The important detail: `Remote_WriteNetNode` does `packet << node.address`,
// i.e. the whole `NetAddress` aggregate. `sizeof(NetAddress)` is 8 (host u32,
// port u16, two trailing alignment bytes), not 6. The game copies those two
// padding bytes verbatim; a receiver must consume them (they are otherwise
// indeterminate). The Rust parser used to read only 6, which shifted every
// following field of packets 30/47 by two bytes per node.
//
// Build & run (Ubuntu 24.04 / Debian bookworm):
//   g++ -O2 -std=c++17 -Wall -Wextra main.cpp -o gen && ./gen > vectors.txt
//
// Output format v1 (one packet per line, '#' lines are comments):
//   packet <number> <hex bytes, lowercase, no separators>
// plus a comment block with the C++ sizes used by the serializers.

#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include "../../../max-cpp-port/src/net_address.hpp"

namespace {

// ---------------------------------------------------------------------------
// NetPacket's write side (max-cpp-port/src/net_packet.cpp + net_packet.hpp).
// Only the templated `operator<<` and the std::string / vector<std::string>
// overloads are used by the lobby packets, so those are copied here.
// ---------------------------------------------------------------------------
class Packet {
    std::vector<std::uint8_t> buffer;

public:
    void write(const void* data, std::size_t length) {
        const auto* bytes = static_cast<const std::uint8_t*>(data);
        buffer.insert(buffer.end(), bytes, bytes + length);
    }

    template <typename T>
    void put(const T& data) {
        write(&data, sizeof(T));
    }

    void put_string(const std::string& string) {
        const auto length = static_cast<std::uint32_t>(string.size());
        put(length);
        write(string.data(), string.size());
    }

    void put_strings(const std::vector<std::string>& strings) {
        const auto count = static_cast<std::uint32_t>(strings.size());
        put(count);
        for (const auto& string : strings) {
            put_string(string);
        }
    }

    const std::vector<std::uint8_t>& bytes() const { return buffer; }
};

// ---------------------------------------------------------------------------
// NetNode layout from max-cpp-port/src/net_node.hpp. The wire does NOT dump the
// struct; Remote_WriteNetNode writes field by field, but `address` is written as
// a whole aggregate, so its padding is part of the wire format.
// ---------------------------------------------------------------------------
struct NetNode {
    std::uint16_t entity_id;
    NetAddress address;
    char name[30];
    bool is_host;
};

static_assert(sizeof(NetAddress) == 8, "NetAddress must carry two padding bytes on the wire");
static_assert(offsetof(NetAddress, host) == 0, "NetAddress.host must be the first field");
static_assert(offsetof(NetAddress, port) == 4, "NetAddress.port follows host without padding");
static_assert(sizeof(bool) == 1, "C++ bool is one byte on this ABI");

// Remote_WriteNetNode (remote.cpp:772).
void write_net_node(Packet& packet, const NetNode& node) {
    packet.put(node.entity_id);
    packet.put(node.address);  // sizeof(NetAddress) == 8, padding included
    packet.write(node.name, sizeof(node.name));
    packet.put(node.is_host);
}

// Remote_NetworkMenu fields used by Remote_WriteGameSettings (networkmenu.hpp).
struct GameSettings {
    std::uint32_t mission_category;
    std::int32_t multi_scenario_id;
    std::vector<std::string> mission_hashes;
    char world_name[30];
    std::int32_t ini_world_index;
    std::int32_t ini_play_mode;
    std::int32_t ini_timer;
    std::int32_t ini_endturn;
    std::int32_t ini_opponent;
    std::int32_t ini_start_gold;
    std::int32_t ini_raw_resource;
    std::int32_t ini_fuel_resource;
    std::int32_t ini_gold_resource;
    std::int32_t ini_alien_derelicts;
    std::int32_t ini_victory_type;
    std::int32_t ini_victory_limit;
    char is_map_changed;
    char is_multi_scenario;
    char default_team_names[4][30];
    std::uint32_t rng_seed;
};

constexpr std::uint32_t MISSION_CATEGORY_MULTI = 4;
constexpr std::uint32_t MISSION_CATEGORY_MULTI_PLAYER_SCENARIO = 7;

// Remote_WriteGameSettings (remote.cpp:247).
void write_game_settings(Packet& packet, const GameSettings& settings) {
    switch (settings.mission_category) {
        case MISSION_CATEGORY_MULTI: {
            packet.put(settings.mission_category);
            packet.put(settings.multi_scenario_id);
        } break;

        case MISSION_CATEGORY_MULTI_PLAYER_SCENARIO: {
            packet.put(settings.mission_category);
            packet.put_strings(settings.mission_hashes);
        } break;

        default: {
            std::fprintf(stderr, "unsupported mission category %u\n", settings.mission_category);
            std::exit(1);
        } break;
    }

    packet.put(settings.world_name);
    packet.put(settings.ini_world_index);
    packet.put(settings.ini_play_mode);
    packet.put(settings.ini_timer);
    packet.put(settings.ini_endturn);
    packet.put(settings.ini_opponent);
    packet.put(settings.ini_start_gold);
    packet.put(settings.ini_raw_resource);
    packet.put(settings.ini_fuel_resource);
    packet.put(settings.ini_gold_resource);
    packet.put(settings.ini_alien_derelicts);
    packet.put(settings.ini_victory_type);
    packet.put(settings.ini_victory_limit);
    packet.put(settings.is_map_changed);
    packet.put(settings.is_multi_scenario);
    packet.put(settings.default_team_names);
    packet.put(settings.rng_seed);
}

// Names in the game are char[30]; fill deterministically so vectors are stable.
void set_name(char (&destination)[30], const char* source) {
    std::memset(destination, 0, sizeof(destination));
    std::strncpy(destination, source, sizeof(destination) - 1);
}

NetNode make_node(std::uint16_t entity_id, std::uint32_t host, std::uint16_t port, std::uint8_t padding,
                  const char* name, bool is_host) {
    NetNode node{};
    node.entity_id = entity_id;
    // Real game code leaves these two bytes uninitialised; set them so vectors
    // are deterministic and so a parser that merely assumes zero is caught.
    std::memset(&node.address, padding, sizeof(node.address));
    node.address.host = host;
    node.address.port = port;
    set_name(node.name, name);
    node.is_host = is_host;
    return node;
}

NetNode host_node() { return make_node(10, 0x0100007F, 31554, 0x00, "Host", true); }
NetNode client_node() { return make_node(11, 0x0100007F, 52001, 0x00, "Rust", false); }

GameSettings common_settings() {
    GameSettings settings{};
    settings.mission_category = MISSION_CATEGORY_MULTI;
    settings.multi_scenario_id = 1;
    set_name(settings.world_name, "MULTI");
    settings.ini_world_index = 0;
    settings.ini_play_mode = 1;
    settings.ini_timer = 3;
    settings.ini_endturn = 0;
    settings.ini_opponent = 1;
    settings.ini_start_gold = 200;
    settings.ini_raw_resource = 1;
    settings.ini_fuel_resource = 1;
    settings.ini_gold_resource = 1;
    settings.ini_alien_derelicts = 0;
    settings.ini_victory_type = 0;
    settings.ini_victory_limit = 0;
    settings.is_map_changed = 0;
    settings.is_multi_scenario = 0;
    set_name(settings.default_team_names[0], "Rust");
    set_name(settings.default_team_names[1], "");
    set_name(settings.default_team_names[2], "");
    set_name(settings.default_team_names[3], "");
    settings.rng_seed = 0x01020304;
    return settings;
}

// Remote_SendNetPacket_30 (remote.cpp:2983): the welcome snapshot sent to a
// newly registered client. Field order and widths copied verbatim.
std::vector<std::uint8_t> packet_30() {
    Packet packet;
    const std::uint16_t newcomer_node = 11;
    const std::uint16_t host_node_id = 10;
    const std::uint16_t team_nodes[4] = {11, 0, 0, 0};
    char team_names[4][30];
    set_name(team_names[0], "Rust");
    set_name(team_names[1], "");
    set_name(team_names[2], "");
    set_name(team_names[3], "");
    const std::vector<NetNode> nodes{host_node(), client_node()};
    const GameSettings settings = common_settings();

    packet.put(static_cast<std::uint8_t>(0x1E + 0x50));  // REMOTE_PACKET_30
    packet.put(newcomer_node);
    packet.put(host_node_id);
    packet.put(team_nodes);
    packet.put(team_names);

    const auto node_count = static_cast<std::uint32_t>(nodes.size());
    packet.put(node_count);
    for (const auto& node : nodes) {
        write_net_node(packet, node);
    }

    write_game_settings(packet, settings);
    return packet.bytes();
}

// Remote_SendNetPacket_47 (remote.cpp:3617): host announces one node. The
// address here deliberately carries 0xCD padding bytes so the Rust test proves
// they are skipped rather than assumed zero.
std::vector<std::uint8_t> packet_47() {
    Packet packet;
    NetNode node = make_node(11, 0x0100007F, 52001, 0xCD, "Rust", false);

    packet.put(static_cast<std::uint8_t>(0x2F + 0x50));
    packet.put(static_cast<std::uint16_t>(10));
    write_net_node(packet, node);
    return packet.bytes();
}

// Remote_SendNetPacket_37 (remote.cpp:3287): host game settings, here for a
// multiplayer scenario, which exercises the vector<string> branch.
std::vector<std::uint8_t> packet_37() {
    Packet packet;
    GameSettings settings = common_settings();
    settings.mission_category = MISSION_CATEGORY_MULTI_PLAYER_SCENARIO;
    settings.multi_scenario_id = 0;
    settings.mission_hashes = {
        "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
    };
    set_name(settings.world_name, "SCENARIO");
    settings.is_map_changed = 1;
    settings.is_multi_scenario = 1;
    set_name(settings.default_team_names[0], "RED");
    set_name(settings.default_team_names[1], "GREEN");
    set_name(settings.default_team_names[2], "BLUE");
    set_name(settings.default_team_names[3], "GRAY");
    settings.rng_seed = 7;

    packet.put(static_cast<std::uint8_t>(0x25 + 0x50));
    packet.put(static_cast<std::uint16_t>(10));
    write_game_settings(packet, settings);
    return packet.bytes();
}

// Remote_SendNetPacket_44 (remote.cpp:3514): host announcement.
std::vector<std::uint8_t> packet_44() {
    Packet packet;

    packet.put(static_cast<std::uint8_t>(0x2C + 0x50));
    packet.put(static_cast<std::uint16_t>(10));
    packet.put(static_cast<std::uint32_t>(0x00000800));
    packet.put_string("Host");
    return packet.bytes();
}

// Remote_SendNetPacket_29 / _28: a bare node id.
std::vector<std::uint8_t> packet_29() {
    Packet packet;
    packet.put(static_cast<std::uint8_t>(0x1D + 0x50));
    packet.put(static_cast<std::uint16_t>(10));
    return packet.bytes();
}

std::vector<std::uint8_t> packet_28() {
    Packet packet;
    packet.put(static_cast<std::uint8_t>(0x1C + 0x50));
    packet.put(static_cast<std::uint16_t>(0));
    return packet.bytes();
}

// Remote_SendNetPacket_35 (remote.cpp:3183): team slot / READY.
std::vector<std::uint8_t> packet_35() {
    Packet packet;
    const std::int8_t team_slot = 2;

    packet.put(static_cast<std::uint8_t>(0x23 + 0x50));
    packet.put(static_cast<std::uint16_t>(10));
    packet.put(static_cast<std::uint16_t>(11));
    packet.put(team_slot);
    packet.put(true);
    packet.put_string("Rust#2");
    return packet.bytes();
}

void print_packet(const char* label, const std::vector<std::uint8_t>& bytes) {
    std::printf("packet %s ", label);
    for (const auto byte : bytes) {
        std::printf("%02x", byte);
    }
    std::printf("  # %zu bytes\n", bytes.size());
}

}  // namespace

int main() {
    std::printf("# lobby wire vectors generated from max-cpp-port (remote.cpp)\n");
    std::printf("# sizeof(NetAddress)=%zu (host u32 + port u16 + %zu padding bytes)\n", sizeof(NetAddress),
                sizeof(NetAddress) - 6);
    std::printf("# sizeof(NetNode)=%zu (not written as a whole; fields are written one by one)\n", sizeof(NetNode));
    std::printf("# Remote_WriteNetNode writes NetAddress as an aggregate, so the padding is on the wire.\n");

    print_packet("28", packet_28());
    print_packet("29", packet_29());
    print_packet("30", packet_30());
    print_packet("35", packet_35());
    print_packet("37", packet_37());
    print_packet("44", packet_44());
    print_packet("47", packet_47());
    return 0;
}
